func contactAddressResolvable(email, domain string) bool {
  email = strings.TrimSpace(email)
  if email == "" || !strings.Contains(email, "@") { return false }
  if strings.EqualFold(email, "info@"+strings.TrimSpace(domain)) { return false }
  return true
}

